use std::fs

fn digit(c: char) -> int {
    let n = c as int
    if n >= 48 && n <= 57 { n - 48 } else if n >= 97 { n - 87 } else { n - 55 }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 { continue }
        let from: int = parts[1].parse().unwrap_or(10)
        let to: int = parts[2].parse().unwrap_or(10)
        let mut v = 0
        for c in parts[0].chars() { v = v * from + digit(c) }
        if v == 0 {
            println("0")
            continue
        }
        let syms = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let mut out = ""
        while v > 0 {
            let d: int = v % to
            let e: int = d + 1
            let ch = syms[d..e]
            out = "${ch}${out}"
            v = v / to
        }
        println(out)
    }
}

